void FParticlePairMidPhase::InitThresholds()
{
	// @todo(chaos): improve this threshold calculation for thin objects? Dynamic thin objects have bigger problems so maybe we don't care
	// @todo(chaos): Spheres and capsules need smaller position tolerance - the restore test doesn't work well with rolling
	const bool bIsDynamic0 = FConstGenericParticleHandle(Particle0)->IsDynamic();
	const bool bIsDynamic1 = FConstGenericParticleHandle(Particle1)->IsDynamic();
	const bool bIsBounded0 = Particle0->HasBounds();
	const bool bIsBounded1 = Particle1->HasBounds();

	// NOTE: If CullDistance ends up smaller than the thresholds used to restore collisions, we can end up missing
	// collisions as the objects move if we restore a "zero contact" manifold after movement greater than the cull distance. 
	// Currently this should not happen, but it is not explicitly ensured by the way the thresholds and CullDistanceScale are calculated.
	// @todo(chaos): Add a way to enforce a CullDistance big enough to support the reuse thresholds
	const FReal CullDistanceReferenceSizeInv = FReal(Chaos_Collision_CullDistanceScaleInverseSize);
	const FReal MinCullDistanceScale = FReal(Chaos_Collision_MinCullDistanceScale);
	const FReal MaxBoundsSize0 = (bIsDynamic0 && bIsBounded0) ? Particle0->LocalBounds().Extents().GetMax() : FReal(0);
	const FReal MaxBoundsSize1 = (bIsDynamic1 && bIsBounded1) ? Particle1->LocalBounds().Extents().GetMax() : FReal(0);
	const FReal CullDistanceScale0 = MaxBoundsSize0 * CullDistanceReferenceSizeInv;
	const FReal CullDistanceScale1 = MaxBoundsSize1 * CullDistanceReferenceSizeInv;
	CullDistanceScale = (FRealSingle)FMath::Max3(CullDistanceScale0, CullDistanceScale1, MinCullDistanceScale);
}

void FParticlePairMidPhase::GenerateCollisions(
	const FReal InCullDistance,
	const FReal InDt,
	const FCollisionContext& Context)
{
	if (!IsValid())
	{
		return;
	}

	CHAOS_MIDPHASE_SCOPE_CYCLE_TIMER(FParticlePairMidPhase_GenerateCollision);

	if (Flags.bIsActive)
	{
		FConstGenericParticleHandle P0 = GetParticle0();
		FConstGenericParticleHandle P1 = GetParticle1();

		FRealSingle Dt = FRealSingle(InDt);

		// CullDistance is scaled by the size of the dynamic objects.
		FRealSingle CullDistance = FRealSingle(InCullDistance) * CullDistanceScale;

const FReal Margin2 = Constraint.GetCollisionMargin1();
const FRigidTransform3 Convex2ToConvex1Transform = Convex2Transform.GetRelativeTransformNoScale(Convex1Transform);

if (!bChaos_Manifold_EnableGjkWarmStart)
{
	Constraint.GetGJKWarmStartData().Reset();

    /// This is implicitly scaled by the [`PhysicsLengthUnit`].
    ///
    /// Default: `MAX` (unbounded)
    pub default_speculative_margin: Scalar,

    /// A contact tolerance that acts as a minimum bound for the [speculative margin](dynamics::ccd#speculative-collision).
    ///
    /// A small, positive contact tolerance helps ensure that contacts are not missed
    /// due to numerical issues or solver jitter for objects that are in continuous
    /// contact, such as pushing against each other.
    ///
    /// Making the contact tolerance too large will have a negative impact on performance,
    /// as contacts will be computed even for objects that are not in close proximity.
    ///
    /// This is implicitly scaled by the [`PhysicsLengthUnit`].
    ///
    /// Default: `0.005`
    pub contact_tolerance: Scalar,

    /// If `true`, the current contacts will be matched with the previous contacts
    /// based on feature IDs or contact positions, and the contact impulses from
    /// the previous frame will be copied over for the new contacts.
    ///
    /// Using these impulses as the initial guess is referred to as *warm starting*,
    /// and it can help the contact solver resolve overlap and stabilize much faster.
    ///
    /// Default: `true`
    pub match_contacts: bool,
}

impl Default for NarrowPhaseConfig {
    fn default() -> Self {
        Self {
            default_speculative_margin: Scalar::MAX,
            contact_tolerance: 0.005,

    });

let relative_linear_velocity: Vector;

// Compute the effective speculative margin, clamping it based on velocities and the maximum bound.
let effective_speculative_margin = {
    let speculative_margin1 =
        speculative_margin1.unwrap_or(*self.default_speculative_margin);
    let speculative_margin2 =
        speculative_margin2.unwrap_or(*self.default_speculative_margin);
    let inv_delta_secs = delta_secs.recip();

    // Clamp velocities to the maximum speculative margins.
    if speculative_margin1 < Scalar::MAX {
        lin_vel1 = lin_vel1.clamp_length_max(speculative_margin1 * inv_delta_secs);
    }
    if speculative_margin2 < Scalar::MAX {
        lin_vel2 = lin_vel2.clamp_length_max(speculative_margin2 * inv_delta_secs);
    }

    // Compute the effective margin based on how much the bodies
    // are expected to move relative to each other.
    relative_linear_velocity = lin_vel2 - lin_vel1;
    delta_secs * relative_linear_velocity.length()
};

// The maximum distance at which contacts are detected.
// At least as large as the contact tolerance.
let max_contact_distance = effective_speculative_margin
    .max(*self.contact_tolerance)
    + collision_margin_sum;

let was_touching = contacts.flags.contains(ContactPairFlags::TOUCHING);

// Save the old manifolds for warm starting.
let old_manifolds = contacts.manifolds.clone();

// TODO: It'd be good to persist the manifolds and let Parry match contacts.
//       This isn't currently done because it requires using Parry's contact manifold type.
// Compute the contact manifolds using the effective speculative margin.
let context = ContactManifoldContext::new(
    collider1.entity,
    collider2.entity,
    collider_context,

let delta_secs = time.delta_seconds_adjusted();
let default_speculative_margin = length_unit.0 * narrow_phase_config.default_speculative_margin;
let contact_tolerance = length_unit.0 * narrow_phase_config.contact_tolerance;
let margin = length_unit.0 * AABB_MARGIN;

let collider_query = colliders.p0();

body_query.par_iter().for_each(
    |(rb_pos, center_of_mass, lin_vel, ang_vel, body_colliders, has_swept_ccd)| {
        for collider_entity in body_colliders.iter() {
            let Ok((
                collider,
                mut aabb,
                mut enlarged_aabb,
                proxy_key,
                pos,
                rot,
                collision_margin,
                speculative_margin,
            )) = (unsafe { collider_query.get_unchecked(collider_entity) })
            else {
                continue;
            };

            let collision_margin = collision_margin.map_or(0.0, |margin| margin.0);
            let speculative_margin = if has_swept_ccd {
                Scalar::MAX
            } else {
                speculative_margin.map_or(default_speculative_margin, |margin| margin.0)
            };

            let context = AabbContext::new(collider_entity, &*collider_context);
            let growth = Vector::splat(contact_tolerance + collision_margin);

            if speculative_margin <= 0.0 {
                *aabb = collider
                    .aabb_with_context(pos.0, *rot, context)
                    .grow(growth);
            } else {
                // If the rigid body is rotating, off-center colliders will orbit around it,
                // which affects their linear velocities. We need to compute the linear velocity
                // at the offset position.
                // TODO: This assumes that the colliders would continue moving in the same direction,
                //       but because they are orbiting, the direction will change. We should take
                //       into account the uniform circular motion.
                let offset = pos.0 - rb_pos.0 - center_of_mass.0;
                #[cfg(feature = "2d")]
                let vel = lin_vel.0 + Vector::new(-ang_vel.0 * offset.y, ang_vel.0 * offset.x);
                #[cfg(feature = "3d")]
                let vel = lin_vel.0 + ang_vel.cross(offset);
                let movement = (vel * delta_secs)
                    .clamp_length_max(speculative_margin.max(contact_tolerance));

FVec3f RelativeMovement = FVec3f(0);
if (!Flags.bIsMACD)
{
	// We increase CullDistance based on velocity (up to a limit for perf with large velocities).
	// NOTE: This somewhat matches the bounds expansion in FPBDRigidsEvolutionGBF::Integrate
	// NOTE: We use PreV here which is the velocity after collisions from the previous tick because we want the 
	// velocity without gravity from this tick applied. This is mainly so that we get the same CullDistance from 
	// one tick to the next, even if one of the particles goes to sleep, and therefore its velocity is now zero 
	// because gravity is no longer applied. Also see FPBDIslandManager::PropagateIslandSleep for other issues 
	// related to velocity and sleeping...
	// NOTE: we used to extend the cull distance for CCD objects, but this is no longer required. The sweep and
	// rewind phase does not use CullDistance, and once rewound we are using normal collision detection where
	// an expanded CullDistance doesn't help and makes perf worse.
	const FRealSingle VMax0 = P0->GetPreVf().GetAbsMax();
	const FRealSingle VMax1 = P1->GetPreVf().GetAbsMax();
	const FRealSingle VMaxDt = FMath::Max(VMax0, VMax1) * Dt;
	const FRealSingle VelocityBoundsMultiplier = FRealSingle(Context.GetSettings().BoundsVelocityInflation);
	const FRealSingle MaxVelocityBoundsExpansion = FRealSingle(Context.GetSettings().MaxVelocityBoundsExpansion);
	if ((VelocityBoundsMultiplier > 0) && (MaxVelocityBoundsExpansion > 0))
	{
		CullDistance += FMath::Min(VelocityBoundsMultiplier * VMaxDt, MaxVelocityBoundsExpansion);
	}
}
else
{
	// Movement-aware collision detection (MACD) takes the relative position change this tick as input
	// We do not expand CullDistance. Depending on the shape pair types involved, the collision detection
	// step will either pad the CullDistance itself, or ideally compare RelativeMovement with the contact 
	// normal when determining what contacts to cull. Eventually all shape pairs should do the latter.
	RelativeMovement = (P0->GetVf() - P1->GetVf()) * Dt;
}

// Run collision detection on all potentially colliding shape pairs

//question: can we enforce this at the API layer? Right now islands contain non dynamic which makes this hard
if (FPBDRigidParticleHandle* PBDParticle = ParticlesArray[Index]->CastToRigidParticle(); PBDParticle)
{
	const bool bIsParticleDynamic = (PBDParticle->ObjectState() == EObjectStateType::Dynamic);
	const bool bIsParticleFrozenDuringBubbleResim = (PBDParticle->ResimType() == EResimType::FrozenDuringResim);
	// We only integrate dynamic particles
	// and when we are resimming, if bubble resim is enabled, we skip integrating particles frozen during resim
	bool bShouldIntegrate = bIsParticleDynamic && !(bIsResimming && bIsBubbleResimEnabled && bIsParticleFrozenDuringBubbleResim);
	if (bShouldIntegrate)
	{
		FPBDRigidParticleHandle& Particle = *PBDParticle;

		FVec3 V = Particle.GetV();
		FVec3 W = Particle.GetW();

		//save off previous velocities
		Particle.SetPreV(V);
		Particle.SetPreW(W);

		for (FForceRule ForceRule : ForceRules)
		{
			ForceRule(Particle, Dt);
		}

		//EulerStepVelocityRule.Apply(Particle, Dt);
		V += Particle.Acceleration() * Dt;
		W += Particle.AngularAcceleration() * Dt;

		//AddImpulsesRule.Apply(Particle, Dt);
		V += Particle.LinearImpulseVelocity();
		W += Particle.AngularImpulseVelocity();
		Particle.LinearImpulseVelocity() = FVec3(0);
		Particle.AngularImpulseVelocity() = FVec3(0);

		//EtherDragRule.Apply(Particle, Dt);

		const FReal LinearDrag = LinearEtherDragOverride >= 0 ? LinearEtherDragOverride : Particle.LinearEtherDrag() * Dt;
		const FReal LinearMultiplier = FMath::Max(FReal(0), FReal(1) - LinearDrag);

// @todo(chaos): move to physics project settings and set these to -1 when we are settled on values...
FRealSingle ChaosSolverVelocityBoundsMultiplier = 1.0f;
FRealSingle ChaosSolverMaxVelocityBoundsExpansion = 3.0f;			// This should probably be a fraction of object size (see FParticlePairMidPhase::GenerateCollisions)
FRealSingle ChaosSolverVelocityBoundsMultiplierMACD = 1.0f;
FRealSingle ChaosSolverMaxVelocityBoundsExpansionMACD = 1000.0f;	// For use when Movement-Aware Collision Detection (MACD) is enabled
